var inp=root.querySelector('.pay4-card-input__inp');
var marks=root.querySelector('.pay4-card-input__marks');
var hint=root.querySelector('.pay4-card-input__hint');
var BR=[
  {k:'visa',n:'Visa',re:/^4/,g:[4,4,4,4],len:16,cvc:3},
  {k:'mc',n:'Mastercard',re:/^(5[1-5]|2[2-7])/,g:[4,4,4,4],len:16,cvc:3},
  {k:'amex',n:'American Express',re:/^3[47]/,g:[4,6,5],len:15,cvc:4},
  {k:'disc',n:'Discover',re:/^(6011|65|64[4-9])/,g:[4,4,4,4],len:16,cvc:3},
  {k:'dine',n:'Diners Club',re:/^3(0[0-5]|[68])/,g:[4,6,4],len:14,cvc:3}
];
var GEN={k:'gen',n:'Card',g:[4,4,4,4],len:16,cvc:3};
function brandOf(d){for(var i=0;i<BR.length;i++){if(BR[i].re.test(d)){return BR[i];}}return GEN;}
function fmt(d,g){var out='',i=0;for(var j=0;j<g.length&&i<d.length;j++){if(out){out+=' ';}out+=d.substr(i,g[j]);i+=g[j];}return out;}
function luhn(d){var s=0,alt=false;for(var i=d.length-1;i>=0;i--){var n=+d.charAt(i);if(alt){n*=2;if(n>9){n-=9;}}s+=n;alt=!alt;}return s%10===0;}
function render(){
  var caret=inp.selectionStart;
  if(caret===null||caret===undefined){caret=inp.value.length;}
  var before=inp.value.slice(0,caret).replace(/[^0-9]/g,'').length;
  var d=inp.value.replace(/[^0-9]/g,'');
  var b=brandOf(d);
  d=d.slice(0,b.len);
  var v=fmt(d,b.g);
  if(inp.value!==v){inp.value=v;}
  var pos=0,seen=0;
  while(pos<v.length&&seen<before){if(v.charAt(pos)!==' '){seen++;}pos++;}
  try{inp.setSelectionRange(pos,pos);}catch(e){}
  marks.setAttribute('data-brand',b.k);
  var full=d.length===b.len;
  var ok=full&&luhn(d);
  root.setAttribute('data-state',d.length===0?'empty':(ok?'valid':(full?'invalid':'typing')));
  if(!d.length){hint.textContent='Visa, Mastercard, Amex and Discover accepted.';}
  else if(ok){hint.textContent=b.n+' · ending '+d.slice(-4)+' · '+b.cvc+'-digit security code';}
  else if(full){hint.textContent='That number fails the checksum — please re-check it.';}
  else{var left=b.len-d.length;hint.textContent=(b.k==='gen'?'Keep typing':b.n)+' · '+left+(left===1?' digit to go':' digits to go');}
}
inp.addEventListener('input',render);
inp.addEventListener('paste',function(){window.setTimeout(render,0);});
render();

