var btn=root.querySelector('.pay4-card-flip__btn');
var txt=root.querySelector('.pay4-card-flip__btntxt');
var card=root.querySelector('.pay4-card-flip__card');
function set(back){
  root.setAttribute('data-face',back?'back':'front');
  btn.setAttribute('aria-pressed',back?'true':'false');
  txt.textContent=back?'Hide security code':'Show security code';
}
function toggle(){set(root.getAttribute('data-face')!=='back');}
btn.addEventListener('click',toggle);
card.addEventListener('click',toggle);
set(false);

