js:
var SUB=248,SHIP=12,RATE=0.08875;
var CODES={SPRING15:{t:'pct',v:.15,d:'15% off your order'},WELCOME10:{t:'flat',v:10,d:'$10 off your first order'},FREESHIP:{t:'ship',v:0,d:'free standard shipping'}};
var form=root.querySelector('.pay4-checkout-promo__form');
var inp=root.querySelector('.pay4-checkout-promo__inp');
var apply=root.querySelector('.pay4-checkout-promo__apply');
var msg=root.querySelector('.pay4-checkout-promo__msg');
var codeEl=root.querySelector('.pay4-checkout-promo__code');
var discEl=root.querySelector('.pay4-checkout-promo__v--down');
var shipEl=root.querySelector('.pay4-checkout-promo__shipv');
var taxEl=root.querySelector('.pay4-checkout-promo__taxv');
var totEl=root.querySelector('.pay4-checkout-promo__tv');
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var applied=null,shown=282.01,raf=0,flashT=0;
function money(n){var neg=n<0;var s=Math.abs(n).toFixed(2).split('.');var i=s[0],out='';while(i.length>3){out=','+i.slice(-3)+out;i=i.slice(0,-3);}return (neg?'−$':'$')+i+out+'.'+s[1];}
function tween(to){
  if(reduce){shown=to;totEl.textContent=money(to);return;}
  var from=shown,t0=null;
  if(raf){window.cancelAnimationFrame(raf);}
  raf=window.requestAnimationFrame(function step(ts){
    if(t0===null){t0=ts;}
    var k=Math.min(1,(ts-t0)/430);var e=1-Math.pow(1-k,3);
    shown=from+(to-from)*e;totEl.textContent=money(shown);
    if(k<1){raf=window.requestAnimationFrame(step);}else{raf=0;shown=to;}
  });
}
function calc(){
  var disc=0,ship=SHIP,c=applied?CODES[applied]:null;
  if(c){if(c.t==='pct'){disc=SUB*c.v;}else if(c.t==='flat'){disc=c.v;}else{ship=0;}}
  disc=Math.round(disc*100)/100;
  var tax=Math.round((SUB-disc)*RATE*100)/100;
  var total=Math.round((SUB-disc+ship+tax)*100)/100;
  root.setAttribute('data-promo',applied?'on':'off');
  root.setAttribute('data-ship',ship===0?'free':'paid');
  if(applied){codeEl.textContent=applied;discEl.textContent=money(-disc);}
  shipEl.textContent=ship===0?'FREE':money(ship);
  taxEl.textContent=money(tax);
  tween(total);
  totEl.setAttribute('data-flash','1');
  if(flashT){window.clearTimeout(flashT);}
  flashT=window.setTimeout(function(){totEl.removeAttribute('data-flash');},560);
