var list=root.querySelector('.pay4-method-picker__list');
var glow=root.querySelector('.pay4-method-picker__glow');
var fee=root.querySelector('.pay4-method-picker__fee');
var opts=Array.prototype.slice.call(root.querySelectorAll('.pay4-method-picker__opt'));
var uid='pay4mp'+Math.random().toString(36).slice(2,9);
function place(lab){glow.style.height=lab.offsetHeight+'px';glow.style.transform='translateY('+lab.offsetTop+'px)';}
function select(lab){
  opts.forEach(function(o){var r=o.querySelector('.pay4-method-picker__radio');var on=o===lab;o.setAttribute('data-sel',on?'1':'0');r.checked=on;});
  place(lab);
  fee.textContent=lab.getAttribute('data-fee');
  fee.setAttribute('data-kind',lab.getAttribute('data-kind')||'ok');
}
opts.forEach(function(o){
  var r=o.querySelector('.pay4-method-picker__radio');
  r.name=uid;
  r.addEventListener('change',function(){if(r.checked){select(o);}});
  r.addEventListener('focus',function(){o.setAttribute('data-focus','1');});
  r.addEventListener('blur',function(){o.removeAttribute('data-focus');});
});
var init=opts.filter(function(o){return o.querySelector('.pay4-method-picker__radio').checked;})[0]||opts[0];
var prev=glow.style.transition;
glow.style.transition='none';
select(init);
window.requestAnimationFrame(function(){glow.style.transition=prev;});
function resync(){var s=opts.filter(function(o){return o.getAttribute('data-sel')==='1';})[0];if(s){place(s);}}
window.addEventListener('resize',resync);
list.addEventListener('scroll',function(){});
if(window.ResizeObserver){new window.ResizeObserver(resync).observe(list);}

