js:
var rows=Array.prototype.slice.call(root.querySelectorAll('.pay4-invoice-lines__tr'));
var subEl=root.querySelector('.pay4-invoice-lines__subv');
var vatEl=root.querySelector('.pay4-invoice-lines__vatv');
var totEl=root.querySelector('.pay4-invoice-lines__totv');
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var cur={sub:0,vat:0,tot:0},raf=0,flashT=0,first=true;
function money(n){var s=Math.abs(n).toFixed(2).split('.');var i=s[0],out='';while(i.length>3){out=','+i.slice(-3)+out;i=i.slice(0,-3);}return '$'+i+out+'.'+s[1];}
function paint(v){subEl.textContent=money(v.sub);vatEl.textContent=money(v.vat);totEl.textContent=money(v.tot);}
function go(to){
  if(reduce||first){cur=to;paint(to);first=false;return;}
  var from={sub:cur.sub,vat:cur.vat,tot:cur.tot},t0=null;
  if(raf){window.cancelAnimationFrame(raf);}
  raf=window.requestAnimationFrame(function step(ts){
    if(t0===null){t0=ts;}
    var k=Math.min(1,(ts-t0)/400),e=1-Math.pow(1-k,3);
    cur={sub:from.sub+(to.sub-from.sub)*e,vat:from.vat+(to.vat-from.vat)*e,tot:from.tot+(to.tot-from.tot)*e};
    paint(cur);
    if(k<1){raf=window.requestAnimationFrame(step);}else{raf=0;cur=to;paint(to);}
  });
}
function calc(flash){
  var sub=0;
  rows.forEach(function(r){if(r.getAttribute('data-on')==='1'){sub+=parseFloat(r.getAttribute('data-amt'));}});
  sub=Math.round(sub*100)/100;
  var vat=Math.round(sub*20)/100;
  go({sub:sub,vat:vat,tot:Math.round((sub+vat)*100)/100});
  if(flash){
    totEl.setAttribute('data-flash','1');
    if(flashT){window.clearTimeout(flashT);}
    flashT=window.setTimeout(function(){totEl.removeAttribute('data-flash');},520);
  }
}
rows.forEach(function(r){
  var b=r.querySelector('.pay4-invoice-lines__tog');
  var nm=r.querySelector('.pay4-invoice-lines__nm');
  b.setAttribute('aria-label','Include '+(nm?nm.textContent.trim():'line')+' on this invoice');
  b.addEventListener('click',function(){
    var on=r.getAttribute('data-on')==='1';
    r.setAttribute('data-on',on?'0':'1');
    b.setAttribute('aria-pressed',on?'false':'true');
    calc(true);
  });
});
calc(false);

