js:
var btn=root.querySelector('.pay4-receipt__copy');
var txt=root.querySelector('.pay4-receipt__copytxt');
var refEl=root.querySelector('.pay4-receipt__ref');
var ref=refEl?refEl.textContent.trim():'';
var original=txt.innerHTML;
var t=0;
function flash(ok){
  root.setAttribute('data-copied',ok?'1':'0');
  txt.textContent=ok?'Copied '+ref:'Press Ctrl/Cmd+C to copy';
  if(t){window.clearTimeout(t);}
  t=window.setTimeout(function(){root.setAttribute('data-copied','0');txt.innerHTML=original;},1700);
}
function fallback(){
  var ta=document.createElement('textarea');
  ta.value=ref;ta.setAttribute('readonly','');
  ta.style.position='absolute';ta.style.left='-9999px';
  root.appendChild(ta);ta.select();
  var ok=false;
  try{ok=document.execCommand('copy');}catch(e){ok=false;}
  root.removeChild(ta);
  flash(ok);
}
btn.setAttribute('aria-label','Copy receipt reference '+ref);
btn.addEventListener('click',function(){
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(ref).then(function(){flash(true);},fallback);
  }else{fallback();}
});

