var STEPS=[
  {t:'Requested',d:'23 Aug, 14:02 · Raised against order NB-2418'},
  {t:'Approved',d:'23 Aug, 16:41 · Approved by Northbank'},
  {t:'Sent to bank',d:'24 Aug, 09:15 · Sent to Visa ···· 4242'},
  {t:'Landed',d:'Est. 27 Aug · Funds back on your card'}
];
var CUR=2;
var sts=Array.prototype.slice.call(root.querySelectorAll('.pay4-refund-track__st'));
var fill=root.querySelector('.pay4-refund-track__fill');
var det=root.querySelector('.pay4-refund-track__det');
function view(i){
  sts.forEach(function(s,j){if(j===i){s.setAttribute('data-view','1');}else{s.removeAttribute('data-view');}});
  det.textContent=STEPS[i].d;
}
sts.forEach(function(s,i){
  var state=i<CUR?'done':(i===CUR?'now':'next');
  s.setAttribute('data-st',state);
  var b=s.querySelector('.pay4-refund-track__btn');
  if(i===CUR){b.setAttribute('aria-current','step');}
  b.setAttribute('aria-label',STEPS[i].t+' — '+(state==='done'?'completed':(state==='now'?'in progress':'pending'))+'. '+STEPS[i].d);
  b.addEventListener('click',function(){view(i);});
});
view(CUR);
window.requestAnimationFrame(function(){
  window.requestAnimationFrame(function(){
    fill.style.width=(CUR/(STEPS.length-1)*100)+'%';
  });
});

