js:
var input=root.querySelector('.pay4-card-input-v2__input');
var msgEl=root.querySelector('.pay4-card-input-v2__msg');
var badge=root.querySelector('.pay4-card-input-v2__badge');
var brands=[{k:'amex',n:'American Express',re:/^3[47]/,len:15,gaps:[4,10]},{k:'visa',n:'Visa',re:/^4/,len:16,gaps:[4,8,12]},{k:'mc',n:'Mastercard',re:/^(5[1-5]|2[2-7])/,len:16,gaps:[4,8,12]},{k:'disc',n:'Discover',re:/^6(011|5)/,len:16,gaps:[4,8,12]}];
var fallback={k:'unknown',n:'Card',len:16,gaps:[4,8,12]};
function detect(d){for(var i=0;i<brands.length;i++){if(brands[i].re.test(d))return brands[i];}return fallback;}
function group(d,b){var out='';for(var i=0;i<d.length;i++){if(b.gaps.indexOf(i)>-1)out+=' ';out+=d.charAt(i);}return out;}
function luhn(d){var sum=0,alt=false;for(var i=d.length-1;i>=0;i--){var n=+d.charAt(i);if(alt){n*=2;if(n>9)n-=9;}sum+=n;alt=!alt;}return d.length>0&&sum%10===0;}
function paint(fromUser){
  var caret=input.selectionStart||0;
  var before=input.value.slice(0,caret).replace(/[^0-9]/g,'').length;
  var digits=input.value.replace(/[^0-9]/g,'');
  var b=detect(digits);
  digits=digits.slice(0,b.len);
  var text=group(digits,b);
  if(text!==input.value){
    input.value=text;
    if(fromUser){var p=0,seen=0;while(p<text.length&&seen<before){if(text.charAt(p)!==' ')seen++;p++;}try{input.setSelectionRange(p,p);}catch(e){}}
  }
  root.setAttribute('data-brand',digits.length>=2?b.k:'unknown');
  var state,txt,mark;
  if(digits.length===0){state='empty';txt='16 digits, spaces added for you';mark='•';}
  else if(digits.length<b.len){var left=b.len-digits.length;state='typing';txt=b.n+' · '+left+' more digit'+(left===1?'':'s');mark='•';}
  else if(luhn(digits)){state='valid';txt=b.n+' accepted · checksum passed';mark='✓';}
  else{state='invalid';txt='Check that number · checksum failed';mark='!';}
  root.setAttribute('data-state',state);
  badge.textContent=mark;
  msgEl.textContent=txt;
}
input.addEventListener('input',function(){paint(true);});
input.addEventListener('paste',function(){window.setTimeout(function(){paint(true);},0);});
input.value='4242424242424242';
paint(false);

