var totEl=root.querySelector('.pay4-promo-sum__tv');
var offEl=root.querySelector('.pay4-promo-sum__off');
var acode=root.querySelector('.pay4-promo-sum__acode');
var shipEl=root.querySelector('.pay4-promo-sum__ship');
var removeBtn=root.querySelector('.pay4-promo-sum__remove');
var base=146.83;
var codes={SPRING15:{off:19.20,note:'SPRING15 · 15% off apparel, ends Sunday'},FREESHIP:{off:7.95,note:'FREESHIP · 2-day shipping on us'},WELCOME10:{off:12.80,note:'WELCOME10 · first-order discount'}};
var nf=new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
var reduce=window.matchMedia?window.matchMedia('(prefers-reduced-motion: reduce)').matches:false;
var shown=base;var token=0;
function tween(to){
  var from=shown,id=++token;shown=to;
  if(reduce||from===to){totEl.textContent='$'+nf.format(to);return;}
  var t0=(window.performance||Date).now();
  function step(t){if(id!==token)return;var p=Math.min(1,(t-t0)/420);var e=1-Math.pow(1-p,3);totEl.textContent='$'+nf.format(from+(to-from)*e);if(p<1)requestAnimationFrame(step);}
  requestAnimationFrame(step);
}
function apply(raw){
  var key=String(raw||'').trim().toUpperCase();
  if(!key){root.setAttribute('data-promo','bad');noteEl.textContent='Enter a code first';return;}
  var hit=codes[key];
  if(!hit){root.setAttribute('data-promo','bad');noteEl.textContent='That code is not recognised';return;}
  root.setAttribute('data-promo','on');
  acode.textContent=key;
  offEl.textContent='−$'+nf.format(hit.off);
  shipEl.textContent=key==='FREESHIP'?'$0.00':'$7.95';
  noteEl.textContent=hit.note;
  tween(Math.round((base-hit.off)*100)/100);
}
form.addEventListener('submit',function(e){e.preventDefault();apply(codeEl.value);});
codeEl.addEventListener('input',function(){if(root.getAttribute('data-promo')==='bad'){root.setAttribute('data-promo','none');noteEl.textContent='Have a code? Try SPRING15 or FREESHIP';}});
removeBtn.addEventListener('click',function(){root.setAttribute('data-promo','none');codeEl.value='';shipEl.textContent='$7.95';noteEl.textContent='Promo removed · code freed up';tween(base);codeEl.focus();});
totEl.textContent='$'+nf.format(base);

