js:
var uid='pay4-pp-'+Math.random().toString(36).slice(2,9);
var radios=root.querySelectorAll('.pay4-pay-picker__radio');
var feev=root.querySelector('.pay4-pay-picker__feev');
var totv=root.querySelector('.pay4-pay-picker__totv');
var formula=root.querySelector('.pay4-pay-picker__formula');
var amount=248.60;
var nf=new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
var reduce=window.matchMedia?window.matchMedia('(prefers-reduced-motion: reduce)').matches:false;
function read(el){return parseFloat(String(el.textContent).replace(/[^0-9.]/g,''))||0;}
function tween(el,to){
  var from=read(el);
  el.pay4Token=(el.pay4Token||0)+1;
  var id=el.pay4Token;
  if(reduce||Math.abs(to-from)<0.005){el.textContent='$'+nf.format(to);return;}
  var t0=(window.performance||Date).now();
  function step(t){if(id!==el.pay4Token)return;var p=Math.min(1,(t-t0)/380);var e=1-Math.pow(1-p,3);el.textContent='$'+nf.format(from+(to-from)*e);if(p<1)requestAnimationFrame(step);}
  requestAnimationFrame(step);
}
function pricing(kind){
  if(kind==='ach')return{fee:Math.min(5,amount*0.008),text:'0.8%, capped at $5.00'};
  return{fee:amount*0.029+0.30,text:'2.9% + $0.30'};
}
function update(){
  var picked=root.querySelector('.pay4-pay-picker__radio:checked');
  if(!picked)return;
  var p=pricing(picked.value);
  var fee=Math.round(p.fee*100)/100;
  root.setAttribute('data-method',picked.value);
  formula.textContent=p.text;
  tween(feev,fee);
  tween(totv,Math.round((amount+fee)*100)/100);
}
for(var i=0;i<radios.length;i++){radios[i].name=uid;radios[i].addEventListener('change',update);}
update();

