  dueEl.textContent='$'+nf.format(sub+tax);
  capEl.textContent='INV-2291 · Meridian Labs · '+on+' of '+rows.length+' lines billed';
  if(flash){dueEl.removeAttribute('data-flash');void dueEl.offsetWidth;dueEl.setAttribute('data-flash','1');}
}
for(var i=0;i<rows.length;i++){rows[i].querySelector('.pay4-inv-lines__cb').addEventListener('change',function(){recalc(true);});}
