function fmt(v){var s=v>0.005?'+':(v<-0.005?'−':'');return s+'$'+nf.format(Math.abs(v));}
function tween(to){
  var from=shown,id=++token;shown=to;
  if(reduce||Math.abs(to-from)<0.005){value.textContent=fmt(to);return;}
  var t0=(window.performance||Date).now();
  function step(t){if(id!==token)return;var p=Math.min(1,(t-t0)/380);var e=1-Math.pow(1-p,3);value.textContent=fmt(from+(to-from)*e);if(p<1)requestAnimationFrame(step);}
  requestAnimationFrame(step);
}
function update(){
  var picked=root.querySelector('.pay4-plan-swap__r:checked');
  if(!picked)return;
  var price=parseFloat(picked.getAttribute('data-price'));
  var delta=Math.round((price-current)*(daysLeft/daysTotal)*100)/100;
  root.style.setProperty('--plw-i',picked.getAttribute('data-idx'));
  if(delta>0.005){root.setAttribute('data-dir','up');label.textContent='Charged today';note.textContent='Prorated for '+daysLeft+' of '+daysTotal+' days · then $'+nf.format(price)+' on Sep 14';}
  else if(delta<-0.005){root.setAttribute('data-dir','down');label.textContent='Credit to next invoice';note.textContent='Prorated for '+daysLeft+' of '+daysTotal+' days · then $'+nf.format(price)+' on Sep 14';}
  else{root.setAttribute('data-dir','flat');label.textContent='No change today';note.textContent='Current plan · renews Sep 14 at $'+nf.format(price);}
  tween(delta);
}
for(var i=0;i<radios.length;i++){radios[i].name=uid;radios[i].addEventListener('change',update);}
update();

