.pay4-refund-trk{--rt-mut:#848DA1;--rt-ok:#3DDC97;box-sizing:border-box;width:100%;padding:11px 12px;background:linear-gradient(180deg,#151A26 0%,#0E121B 100%);border:1px solid rgba(255,255,255,.09);border-radius:14px;color:#E9EDF6;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-variant-numeric:tabular-nums;-webkit-font-smoothing:antialiased}
.pay4-refund-trk__top{display:flex;align-items:baseline;justify-content:space-between;gap:8px}
.pay4-refund-trk__amt{font-size:16px;font-weight:700;color:var(--rt-ok);letter-spacing:-.01em}
.pay4-refund-trk__tag{font-size:9.5px;color:var(--rt-mut)}
.pay4-refund-trk__track{position:relative;margin-top:12px;height:32px}
.pay4-refund-trk__rail{position:absolute;left:12.5%;right:12.5%;top:6px;height:2px;border-radius:2px;background:rgba(255,255,255,.11)}
.pay4-refund-trk__fill{position:absolute;left:12.5%;top:6px;height:2px;width:calc(75% * var(--prt-p,0));border-radius:2px;background:linear-gradient(90deg,#2E9E76,#3DDC97);transition:width .55s cubic-bezier(.3,.85,.25,1)}
.pay4-refund-trk__steps{display:flex;margin:0;padding:0;list-style:none}
.pay4-refund-trk__st{flex:1 1 0;display:flex;flex-direction:column;align-items:center;gap:6px;font-size:8.5px;letter-spacing:.02em;color:#5F6879;text-align:center}
.pay4-refund-trk__dot{position:relative;z-index:1;width:14px;height:14px;border-radius:50%;box-sizing:border-box;background:#0C1019;border:2px solid rgba(255,255,255,.18);transition:background .3s ease,border-color .3s ease}
.pay4-refund-trk__st[data-s='done'] .pay4-refund-trk__dot{background:var(--rt-ok);border-color:var(--rt-ok)}
.pay4-refund-trk__st[data-s='done'] .pay4-refund-trk__dot::after{content:'✓';position:absolute;left:0;top:0;right:0;bottom:0;display:flex;align-items:center;justify-content:center;font-size:7.5px;font-weight:900;color:#06130D}
.pay4-refund-trk__st[data-s='now'] .pay4-refund-trk__dot{background:#0C1A15;border-color:var(--rt-ok)}
.pay4-refund-trk__st[data-s='now'] .pay4-refund-trk__dot::before{content:'';position:absolute;left:-5px;top:-5px;right:-5px;bottom:-5px;border-radius:50%;border:1px solid rgba(61,220,151,.5);animation:pay4-rt-pulse 1.9s ease-out infinite}
@keyframes pay4-rt-pulse{0%{transform:scale(.7);opacity:.9}100%{transform:scale(1.25);opacity:0}}
.pay4-refund-trk__st[data-s='done'] .pay4-refund-trk__lb{color:#9AA4B8}
.pay4-refund-trk__st[data-s='now'] .pay4-refund-trk__lb{color:#fff;font-weight:600}
.pay4-refund-trk__foot{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:4px}
.pay4-refund-trk__msg{flex:1 1 auto;margin:0;font-size:9px;line-height:1.45;color:var(--rt-mut)}
.pay4-refund-trk__btn{flex:0 0 auto;padding:5px 9px;border:1px solid rgba(255,255,255,.14);border-radius:7px;background:rgba(255,255,255,.06);color:#E9EDF6;font:inherit;font-size:9.5px;font-weight:600;cursor:pointer;transition:background .16s ease,transform .1s ease,opacity .16s ease}
.pay4-refund-trk__btn:hover{background:rgba(255,255,255,.13)}
.pay4-refund-trk__btn:active{transform:translateY(1px)}
.pay4-refund-trk__btn:focus-visible{outline:2px solid #9DB8FF;outline-offset:2px}
.pay4-refund-trk__btn[disabled]{cursor:default;opacity:.55;background:rgba(61,220,151,.12);border-color:rgba(61,220,151,.32);color:var(--rt-ok)}
@media (prefers-reduced-motion:reduce){.pay4-refund-trk__fill{transition:none}.pay4-refund-trk__st[data-s='now'] .pay4-refund-trk__dot::before{animation:none;opacity:.5}}

js:
var steps=root.querySelectorAll('.pay4-refund-trk__st');
var msg=root.querySelector('.pay4-refund-trk__msg');
var btn=root.querySelector('.pay4-refund-trk__btn');
var copy=['Requested Aug 22 · reversal queued with Northbay','Approved Aug 23 · merchant released the funds','Sent to Visa ····4242 on Aug 24 · banks post in 3–5 business days','Posted Aug 27 · −$84.20 back on Visa ····4242'];
var step=parseInt(root.getAttribute('data-step'),10)||0;
function render(){
  root.setAttribute('data-step',String(step));
  root.style.setProperty('--prt-p',(step/(steps.length-1)).toFixed(4));
  for(var i=0;i<steps.length;i++){steps[i].setAttribute('data-s',i<step?'done':(i===step?'now':'next'));}
  if(step===steps.length-1){steps[step].setAttribute('data-s','done');btn.textContent='Complete';btn.disabled=true;}
  msg.textContent=copy[step];
}
btn.addEventListener('click',function(){if(step<steps.length-1){step++;render();}});
render();
